-- ===== 20261024000000_friendships.sql =====
-- Closes a hole that let anyone forge an accepted friendship, lets people decline
-- requests, unfriend and block, and allows only one request per pair.
-- Safe to run more than once.

-- Helpers used by policies live in a schema the REST API does not expose, so
-- they cannot be called directly to probe other people's data.
create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;

-- A request sent both ways (A->B and B->A) left two rows for one friendship.
-- Keep the accepted row, or the older one when both have the same status.
delete from public.friend_requests f
using public.friend_requests g
where f.id <> g.id
  and least(f.requester_id, f.target_id) = least(g.requester_id, g.target_id)
  and greatest(f.requester_id, f.target_id) = greatest(g.requester_id, g.target_id)
  and (
    (f.status = 'pending' and g.status = 'accepted') or
    (f.status = g.status and (f.created_at, f.id) > (g.created_at, g.id))
  );

create unique index if not exists friend_requests_pair_key
  on public.friend_requests (least(requester_id, target_id), greatest(requester_id, target_id));

-- Only the status column may change. The update policy alone let the recipient
-- rewrite requester_id and so "accept" a friendship with anyone.
revoke all on public.friend_requests from anon;
revoke update on public.friend_requests from authenticated;
grant update (status) on public.friend_requests to authenticated;

-- Blocking: the blocked person can no longer send requests or find the blocker.
create table if not exists public.friend_blocks (
  blocker_id uuid not null references public.profiles(id) on delete cascade,
  blocked_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id),
  check (blocker_id <> blocked_id)
);
alter table public.friend_blocks enable row level security;
revoke all on public.friend_blocks from anon, authenticated;
grant select, insert, delete on public.friend_blocks to authenticated;

drop policy if exists "Users see their blocks" on public.friend_blocks;
create policy "Users see their blocks" on public.friend_blocks
  for select to authenticated using (blocker_id = (select auth.uid()));
drop policy if exists "Users block others" on public.friend_blocks;
create policy "Users block others" on public.friend_blocks
  for insert to authenticated with check (blocker_id = (select auth.uid()));
drop policy if exists "Users unblock others" on public.friend_blocks;
create policy "Users unblock others" on public.friend_blocks
  for delete to authenticated using (blocker_id = (select auth.uid()));

-- True when either person blocked the other (the blocked side cannot read the row).
create or replace function private.blocked_between(a uuid, b uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.friend_blocks k
    where (k.blocker_id = a and k.blocked_id = b) or (k.blocker_id = b and k.blocked_id = a)
  );
$$;
-- Only the definer triggers below call it.
revoke all on function private.blocked_between(uuid, uuid) from public, anon, authenticated;

-- Blocking ends any friendship or pending request between the two.
create or replace function private.friend_blocks_after_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.friend_requests
  where (requester_id = new.blocker_id and target_id = new.blocked_id)
     or (requester_id = new.blocked_id and target_id = new.blocker_id);
  return new;
end;
$$;
revoke all on function private.friend_blocks_after_insert() from public, anon, authenticated;
drop trigger if exists friend_blocks_after_insert on public.friend_blocks;
create trigger friend_blocks_after_insert after insert on public.friend_blocks
  for each row execute function private.friend_blocks_after_insert();

-- Every request ever sent, so cancelling requests does not reset the daily limit.
create table if not exists private.friend_request_log (
  requester_id uuid not null,
  sent_at timestamptz not null default now()
);
create index if not exists friend_request_log_idx on private.friend_request_log (requester_id, sent_at);

-- New requests: server time, at most 20 a day, never to or from someone blocked.
-- A request to someone who blocked the sender is dropped without an error
-- (and still counts), so the block isn't announced; the sender can still
-- notice that the request never appears.
create or replace function private.friend_requests_guard()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' then
    if new.requester_id <> old.requester_id or new.target_id <> old.target_id or new.created_at <> old.created_at then
      raise exception 'Only the request status can change' using errcode = '42501';
    end if;
    return new;
  end if;
  new.created_at := now();
  if exists (select 1 from public.friend_blocks k where k.blocker_id = new.requester_id and k.blocked_id = new.target_id) then
    raise exception 'Unblock this person first' using errcode = '42501';
  end if;
  -- One sender at a time, so parallel requests cannot all pass the count.
  perform pg_advisory_xact_lock(hashtextextended('friend_request:' || new.requester_id::text, 0));
  delete from private.friend_request_log where sent_at < now() - interval '2 days';
  if (
    select count(*) from private.friend_request_log
    where requester_id = new.requester_id and sent_at > now() - interval '1 day'
  ) >= 20 then
    raise exception 'Too many friend requests today. Try again tomorrow.' using errcode = '54000';
  end if;
  insert into private.friend_request_log (requester_id) values (new.requester_id);
  if exists (select 1 from public.friend_blocks k where k.blocker_id = new.target_id and k.blocked_id = new.requester_id) then
    return null;
  end if;
  return new;
end;
$$;
revoke all on function private.friend_requests_guard() from public, anon, authenticated;
drop trigger if exists friend_requests_guard on public.friend_requests;
drop function if exists public.friend_requests_guard();
create trigger friend_requests_guard before insert or update on public.friend_requests
  for each row execute function private.friend_requests_guard();

-- Either person can withdraw: cancel an outgoing request, decline an incoming one, or unfriend.
drop policy if exists "Participants remove friend requests" on public.friend_requests;
create policy "Participants remove friend requests" on public.friend_requests
  for delete to authenticated using (requester_id = (select auth.uid()) or target_id = (select auth.uid()));

-- True when the signed-in user and `other` are accepted friends.
create or replace function private.is_friend(other uuid)
returns boolean
language sql
stable
security invoker
set search_path = ''
as $$
  select exists (
    select 1 from public.friend_requests f
    where f.status = 'accepted'
      and ((f.requester_id = (select auth.uid()) and f.target_id = other)
        or (f.target_id = (select auth.uid()) and f.requester_id = other))
  );
$$;
revoke all on function private.is_friend(uuid) from public, anon;
grant execute on function private.is_friend(uuid) to authenticated;
drop function if exists public.is_friend(uuid);

-- ===== 20261024000001_privacy.sql =====
-- Privacy for a young user base:
--   * usernames can no longer be listed; adding a friend needs the exact name,
--     and lookups are rate-limited
--   * friends see a summary, not full histories; weight is shared only if the
--     user turns it on, stats only if they publish them
--   * leaderboard totals are computed from synced history, not taken on trust
--   * a deleted weigh-in stays deleted even if an older app version re-uploads it
--   * profiles are created on sign-up, so a taken username can't break sync
--   * sign-ups must confirm their age (14+) or a parent's permission
--   * users can delete their own account and all its data
-- Requires 20261024000000_friendships.sql and the 2026-10-23 workout-sync
-- migrations. Safe to run more than once.

alter table public.profiles add column if not exists share_weight boolean not null default false;

-- Profiles: yourself, and anyone you are friends with or have a pending request with.
drop policy if exists "Authenticated users can find usernames" on public.profiles;
drop policy if exists "Users read related profiles" on public.profiles;
create policy "Users read related profiles" on public.profiles
  for select to authenticated using (
    id = (select auth.uid()) or exists (
      select 1 from public.friend_requests f
      where (f.requester_id = (select auth.uid()) and f.target_id = profiles.id)
         or (f.target_id = (select auth.uid()) and f.requester_id = profiles.id)
    )
  );

-- Exact-match lookup for "add friend": 30 lookups an hour, nothing for unknown
-- names or for people who blocked you.
create table if not exists private.profile_lookups (
  user_id uuid not null,
  looked_up_at timestamptz not null default now()
);
create index if not exists profile_lookups_user_idx on private.profile_lookups (user_id, looked_up_at);

drop function if exists public.find_profile(text);
create function public.find_profile(name text)
returns table (id uuid, username text)
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  me uuid := auth.uid();
begin
  if me is null then
    return;
  end if;
  -- One lookup at a time per user, so parallel calls cannot all pass the count.
  perform pg_advisory_xact_lock(hashtextextended('profile_lookup:' || me::text, 0));
  delete from private.profile_lookups where looked_up_at < now() - interval '1 day';
  if (select count(*) from private.profile_lookups l where l.user_id = me and l.looked_up_at > now() - interval '1 hour') >= 30 then
    raise exception 'Too many searches. Try again in an hour.' using errcode = '54000';
  end if;
  insert into private.profile_lookups (user_id) values (me);
  return query
    select p.id, p.username from public.profiles p
    where p.username = lower(btrim(name))
      and not exists (select 1 from public.friend_blocks k where k.blocker_id = p.id and k.blocked_id = me);
end;
$$;
revoke all on function public.find_profile(text) from public, anon;
grant execute on function public.find_profile(text) to authenticated;

-- Usernames of the people you blocked (you cannot read their profiles any more).
create or replace function public.my_blocks()
returns table (blocked_id uuid, username text, created_at timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select k.blocked_id, p.username, k.created_at
  from public.friend_blocks k join public.profiles p on p.id = k.blocked_id
  where k.blocker_id = auth.uid()
  order by k.created_at desc;
$$;
revoke all on function public.my_blocks() from public, anon;
grant execute on function public.my_blocks() to authenticated;

-- Sign-ups must confirm "14 or older, or a parent or guardian agreed". The
-- confirmation is kept where the user cannot change it later.
create table if not exists private.account_consents (
  user_id uuid primary key references auth.users(id) on delete cascade,
  age_confirmed_at timestamptz not null default now()
);

-- Create the profile when the account is created. A taken or invalid username
-- gets a random one; the app then asks the user to pick another.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  wanted text := lower(coalesce(new.raw_user_meta_data ->> 'username', ''));
begin
  if coalesce(new.raw_user_meta_data ->> 'age_confirmed', '') <> 'true' then
    raise exception 'Please confirm you are 14 or older, or that a parent or guardian agreed.' using errcode = '23514';
  end if;
  insert into private.account_consents (user_id) values (new.id) on conflict (user_id) do nothing;
  if wanted !~ '^[a-z0-9_]{3,20}$' or exists (select 1 from public.profiles where username = wanted) then
    wanted := 'user_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);
  end if;
  insert into public.profiles (id, username) values (new.id, wanted) on conflict (id) do nothing;
  return new;
end;
$$;
revoke all on function public.handle_new_user() from public, anon, authenticated;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- Full weigh-in history and plans are private to the owner from now on.
drop policy if exists "Owners and accepted friends read body weight" on public.body_weight_logs;
drop policy if exists "Users read their own body weight" on public.body_weight_logs;
create policy "Users read their own body weight" on public.body_weight_logs
  for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists "Owners and accepted friends read workout plans" on public.workout_plans;
drop policy if exists "Users read their own workout plan" on public.workout_plans;
create policy "Users read their own workout plan" on public.workout_plans
  for select to authenticated using (user_id = (select auth.uid()));

-- Deleted weigh-ins: a later write with an older timestamp (an old app
-- version re-uploading its copy) is ignored. A newer entry for the day wins.
create table if not exists private.body_weight_tombstones (
  user_id uuid not null references public.profiles(id) on delete cascade,
  log_date date not null,
  deleted_at timestamptz not null default now(),
  primary key (user_id, log_date)
);

create or replace function private.body_weight_after_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- Account deletion cascades here too; skip when the profile is gone.
  if exists (select 1 from public.profiles where id = old.user_id) then
    insert into private.body_weight_tombstones (user_id, log_date, deleted_at)
    values (old.user_id, old.log_date, now())
    on conflict (user_id, log_date) do update set deleted_at = excluded.deleted_at;
  end if;
  return old;
end;
$$;

create or replace function private.body_weight_before_write()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  gone timestamptz;
begin
  select t.deleted_at into gone from private.body_weight_tombstones t
  where t.user_id = new.user_id and t.log_date = new.log_date;
  if gone is not null then
    if coalesce(new.updated_at, now()) <= gone then
      return null;
    end if;
    delete from private.body_weight_tombstones where user_id = new.user_id and log_date = new.log_date;
  end if;
  return new;
end;
$$;
revoke all on function private.body_weight_after_delete() from public, anon, authenticated;
revoke all on function private.body_weight_before_write() from public, anon, authenticated;
drop trigger if exists body_weight_after_delete on public.body_weight_logs;
create trigger body_weight_after_delete after delete on public.body_weight_logs
  for each row execute function private.body_weight_after_delete();
drop trigger if exists body_weight_before_write on public.body_weight_logs;
create trigger body_weight_before_write before insert or update on public.body_weight_logs
  for each row execute function private.body_weight_before_write();

-- Weigh-ins uploaded by a phone running this version, stored with server time.
-- An entry marked fresh was changed on that phone since its last upload and
-- overrides a deletion made elsewhere. Any other entry is a copy the phone
-- holds: a deletion recorded here wins unless the copy is newer than it
-- (updated_at, the time the entry was last changed), so stale copies stay
-- deleted and entries made after the deletion survive.
-- Returns one row per entry: outcome 'saved' (with the server time), 'deleted'
-- (a deletion recorded here wins) or 'date' (implausible date, not stored).
drop function if exists public.save_my_weights(jsonb);
create function public.save_my_weights(entries jsonb)
returns table (log_date date, updated_at timestamptz, outcome text)
language plpgsql
security definer
set search_path = ''
as $$
#variable_conflict use_column
declare
  e jsonb;
  d date;
begin
  if auth.uid() is null then
    raise exception 'Not signed in' using errcode = '42501';
  end if;
  if jsonb_typeof(entries) <> 'array' or jsonb_array_length(entries) > 400 then
    raise exception 'Send up to 400 weigh-ins at a time' using errcode = '22023';
  end if;
  for e in select value from jsonb_array_elements(entries) loop
    d := (e ->> 'log_date')::date;
    -- Implausible dates (a phone with a wrong clock) are skipped, not fatal.
    if d < date '1900-01-01' or d > current_date + 2 then
      log_date := d; updated_at := null; outcome := 'date';
      return next;
      continue;
    end if;
    if coalesce((e ->> 'fresh')::boolean, false) then
      delete from private.body_weight_tombstones t where t.user_id = auth.uid() and t.log_date = d;
    elsif exists (
      select 1 from private.body_weight_tombstones t
      where t.user_id = auth.uid() and t.log_date = d
        and (e ->> 'updated_at' is null or t.deleted_at >= (e ->> 'updated_at')::timestamptz)
    ) then
      log_date := d; updated_at := null; outcome := 'deleted';
      return next;
      continue;
    end if;
    insert into public.body_weight_logs as b (user_id, log_date, weight_kg, updated_at)
    values (auth.uid(), d, (e ->> 'weight_kg')::numeric, now())
    on conflict (user_id, log_date) do update set weight_kg = excluded.weight_kg, updated_at = now();
    log_date := d;
    updated_at := now();
    outcome := 'saved';
    return next;
  end loop;
end;
$$;
revoke all on function public.save_my_weights(jsonb) from public, anon;
grant execute on function public.save_my_weights(jsonb) to authenticated;

-- Totals from a synced history (sessions, seconds, kg x reps). Values that are
-- not plain numbers count as zero.
create or replace function private.workout_totals(logs jsonb)
returns table (workouts integer, seconds bigint, volume bigint)
language sql
immutable
set search_path = ''
as $$
  with sessions as (
    select s.value as s
    from jsonb_each(case when jsonb_typeof(logs) = 'object' then logs else '{}'::jsonb end) d
    cross join lateral jsonb_array_elements(case when jsonb_typeof(d.value) = 'array' then d.value else '[]'::jsonb end) s
    where jsonb_typeof(s.value) = 'object'
  ), sets as (
    select x.value as x
    from sessions
    cross join lateral jsonb_array_elements(case when jsonb_typeof(sessions.s -> 'exercises') = 'array' then sessions.s -> 'exercises' else '[]'::jsonb end) e
    cross join lateral jsonb_array_elements(case when jsonb_typeof(e.value -> 'sets') = 'array' then e.value -> 'sets' else '[]'::jsonb end) x
    where jsonb_typeof(x.value) = 'object'
  )
  select
    (select count(*) from sessions)::integer,
    (select coalesce(sum(case when (s ->> 'duration') ~ '^\d{1,7}(\.\d+)?$' then (s ->> 'duration')::numeric else 0 end), 0) from sessions)::bigint,
    (select coalesce(sum(
      (case when (x ->> 'w') ~ '^\d{1,4}(\.\d+)?$' then (x ->> 'w')::numeric else 0 end) *
      (case when (x ->> 'r') ~ '^\d{1,4}(\.\d+)?$' then (x ->> 'r')::numeric else 0 end)), 0) from sets)::bigint;
$$;
revoke all on function private.workout_totals(jsonb) from public, anon, authenticated;

-- What friends see about each other. Stats and plan counts only for people who
-- published them (a leaderboard row); totals come from their synced history
-- when there is one. Streaks are reported by the app, since they depend on the
-- weekly plan.
drop function if exists public.friend_summaries();
create function public.friend_summaries()
returns table (
  user_id uuid, username text, workouts_count integer, volume_kg_reps bigint,
  total_seconds bigint, current_streak integer, best_streak integer,
  weight_kg numeric, weight_date date, routines integer, exercises integer
)
language sql
stable
security definer
set search_path = ''
as $$
  with people as (
    select auth.uid() as id
    union
    select case when f.requester_id = auth.uid() then f.target_id else f.requester_id end
    from public.friend_requests f
    where f.status = 'accepted' and (f.requester_id = auth.uid() or f.target_id = auth.uid())
  )
  select p.id, p.username,
         case when s.user_id is not null then coalesce(t.workouts, s.workouts_count) end,
         case when s.user_id is not null then coalesce(t.volume, s.volume_kg_reps) end,
         case when s.user_id is not null then coalesce(t.seconds, s.total_seconds) end,
         s.current_streak,
         s.best_streak,
         case when p.share_weight or p.id = auth.uid() then w.weight_kg end,
         case when p.share_weight or p.id = auth.uid() then w.log_date end,
         case when s.user_id is not null or p.id = auth.uid() then
           coalesce((select count(*) from jsonb_object_keys(case when jsonb_typeof(wp.plan -> 'workouts') = 'object' then wp.plan -> 'workouts' else '{}'::jsonb end)), 0)::integer end,
         case when s.user_id is not null or p.id = auth.uid() then
           coalesce((select sum(jsonb_array_length(v)) from jsonb_each(case when jsonb_typeof(wp.plan -> 'workouts') = 'object' then wp.plan -> 'workouts' else '{}'::jsonb end) as e(k, v)
                     where jsonb_typeof(v) = 'array'), 0)::integer end
  from people x
  join public.profiles p on p.id = x.id
  left join public.leaderboard_stats s on s.user_id = p.id
  left join public.workout_plans wp on wp.user_id = p.id
  left join public.workout_data wd on wd.user_id = p.id and s.user_id is not null
  left join lateral private.workout_totals(wd.logs) t on wd.user_id is not null
  left join lateral (
    select b.weight_kg, b.log_date from public.body_weight_logs b
    where b.user_id = p.id order by b.log_date desc limit 1
  ) w on true
  where auth.uid() is not null;
$$;
revoke all on function public.friend_summaries() from public, anon;
grant execute on function public.friend_summaries() to authenticated;

-- Shared routines: bounded size, and an index for the friends feed.
create index if not exists shared_workouts_owner_idx on public.shared_workouts (owner_id);
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'shared_workouts_size_check') then
    alter table public.shared_workouts add constraint shared_workouts_size_check
      check (jsonb_array_length(workout) <= 60 and pg_column_size(workout) < 32768) not valid;
  end if;
end;
$$;

-- Deletes the signed-in account. Every table cascades from auth.users.
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if auth.uid() is null then
    raise exception 'Not signed in' using errcode = '42501';
  end if;
  -- Sign-in records mention the email address; remove them too.
  delete from auth.audit_log_entries a
  where a.payload ->> 'actor_id' = auth.uid()::text
     or a.payload -> 'traits' ->> 'user_id' = auth.uid()::text
     or a.payload ->> 'actor_username' = (select email from auth.users where id = auth.uid());
  -- Rate-limit records are keyed by the user id; they go too.
  delete from private.friend_request_log where requester_id = auth.uid();
  delete from private.profile_lookups where user_id = auth.uid();
  delete from auth.flow_state where user_id = auth.uid();
  delete from auth.users where id = auth.uid();
end;
$$;
revoke all on function public.delete_my_account() from public, anon;
grant execute on function public.delete_my_account() to authenticated;

-- Changing the username goes through this function: a taken name would
-- otherwise confirm that an account exists, so each attempt counts toward the
-- same 30-an-hour budget as username lookups.
create or replace function public.change_username(name text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  me uuid := auth.uid();
  wanted text := lower(btrim(coalesce(name, '')));
begin
  if me is null then
    raise exception 'Not signed in' using errcode = '42501';
  end if;
  if wanted !~ '^[a-z0-9_]{3,20}$' then
    return 'invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('profile_lookup:' || me::text, 0));
  if (select count(*) from private.profile_lookups l where l.user_id = me and l.looked_up_at > now() - interval '1 hour') >= 30 then
    raise exception 'Too many username checks. Try again in an hour.' using errcode = '54000';
  end if;
  insert into private.profile_lookups (user_id) values (me);
  perform set_config('app.username_change', 'on', true);
  begin
    update public.profiles set username = wanted where id = me;
  exception when unique_violation then
    return 'taken';
  end;
  return 'ok';
end;
$$;
revoke all on function public.change_username(text) from public, anon;
grant execute on function public.change_username(text) to authenticated;

-- Any other update keeps the username as it is (no error, so nothing is
-- revealed, and the original app's profile upsert keeps working).
create or replace function private.profiles_keep_username()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.username is distinct from old.username and current_setting('app.username_change', true) is distinct from 'on' then
    new.username := old.username;
  end if;
  return new;
end;
$$;
revoke all on function private.profiles_keep_username() from public, anon, authenticated;
drop trigger if exists profiles_keep_username on public.profiles;
create trigger profiles_keep_username before update on public.profiles
  for each row execute function private.profiles_keep_username();

-- ===== 20261024000002_gym_dates.sql =====
-- Gym dates: plan a gym visit (now or later) and let friends join.
-- Visible only to the host's accepted friends, or to the invited subset of them.
-- Requires 20261024000000_friendships.sql. Safe to run more than once.

create table if not exists public.gym_dates (
  id uuid primary key default gen_random_uuid(),
  host_id uuid not null references public.profiles(id) on delete cascade,
  starts_at timestamptz not null,
  duration_min integer not null default 90 check (duration_min between 15 and 360),
  gym text not null check (char_length(btrim(gym)) between 1 and 60),
  workout text check (workout is null or char_length(workout) <= 40),
  note text check (note is null or char_length(note) <= 200),
  invite_only boolean not null default false,
  cancelled_at timestamptz,
  created_at timestamptz not null default now(),
  -- Bumped whenever a reply or invite changes, so live updates can be sent
  -- through this table alone (see the realtime note at the end).
  activity_at timestamptz not null default now()
);
alter table public.gym_dates add column if not exists activity_at timestamptz not null default now();
create index if not exists gym_dates_starts_at_idx on public.gym_dates (starts_at);
create index if not exists gym_dates_host_idx on public.gym_dates (host_id);

create table if not exists public.gym_date_invites (
  date_id uuid not null references public.gym_dates(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  primary key (date_id, user_id)
);
create index if not exists gym_date_invites_user_idx on public.gym_date_invites (user_id);

create table if not exists public.gym_date_rsvps (
  date_id uuid not null references public.gym_dates(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  status text not null check (status in ('going', 'maybe', 'no')),
  checked_in_at timestamptz,
  updated_at timestamptz not null default now(),
  primary key (date_id, user_id)
);
create index if not exists gym_date_rsvps_user_idx on public.gym_date_rsvps (user_id);

alter table public.gym_dates enable row level security;
alter table public.gym_date_invites enable row level security;
alter table public.gym_date_rsvps enable row level security;
-- Least privilege: nothing for anon; only the verbs and columns the app needs.
-- Hosts cancel dates rather than deleting or editing them, so replies and
-- check-ins always refer to the time, place and audience they were given for.
revoke all on public.gym_dates, public.gym_date_invites, public.gym_date_rsvps from anon, authenticated;
grant select, insert on public.gym_dates to authenticated;
grant update (cancelled_at) on public.gym_dates to authenticated;
grant select, insert, delete on public.gym_date_invites to authenticated;
grant select, insert, delete on public.gym_date_rsvps to authenticated;
-- date_id and user_id are listed only so upserts work; the trigger below
-- refuses any change to them.
grant update (date_id, user_id, status, checked_in_at) on public.gym_date_rsvps to authenticated;

-- Policies on these tables reference each other, so visibility is decided by
-- security-definer helpers that read the tables directly (no policy recursion).
-- Each answers only for the signed-in user, and they live in the unexposed
-- private schema so they cannot be called through the API.
create or replace function private.gym_date_visible(d uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.gym_dates g
    where g.id = d
      and (g.host_id = auth.uid() or (
        exists (
          select 1 from public.friend_requests f
          where f.status = 'accepted'
            and ((f.requester_id = auth.uid() and f.target_id = g.host_id)
              or (f.target_id = auth.uid() and f.requester_id = g.host_id))
        )
        and (not g.invite_only or exists (
          select 1 from public.gym_date_invites i where i.date_id = g.id and i.user_id = auth.uid()
        ))
      ))
  );
$$;

create or replace function private.gym_date_is_host(d uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.gym_dates g where g.id = d and g.host_id = auth.uid());
$$;

-- Visible to the caller, not cancelled and not over yet.
create or replace function private.gym_date_open(d uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select private.gym_date_visible(d) and exists (
    select 1 from public.gym_dates g
    where g.id = d and g.cancelled_at is null
      and g.starts_at + make_interval(mins => g.duration_min) > now()
  );
$$;

revoke all on function private.gym_date_visible(uuid) from public, anon;
revoke all on function private.gym_date_is_host(uuid) from public, anon;
revoke all on function private.gym_date_open(uuid) from public, anon;
grant execute on function private.gym_date_visible(uuid) to authenticated;
grant execute on function private.gym_date_is_host(uuid) to authenticated;
grant execute on function private.gym_date_open(uuid) to authenticated;

drop policy if exists "Host and invited friends read gym dates" on public.gym_dates;
create policy "Host and invited friends read gym dates" on public.gym_dates
  for select to authenticated using (host_id = (select auth.uid()) or private.gym_date_visible(id));
drop policy if exists "Users host their own gym dates" on public.gym_dates;
create policy "Users host their own gym dates" on public.gym_dates
  for insert to authenticated with check (host_id = (select auth.uid()));
drop policy if exists "Hosts edit their gym dates" on public.gym_dates;
create policy "Hosts edit their gym dates" on public.gym_dates
  for update to authenticated using (host_id = (select auth.uid())) with check (host_id = (select auth.uid()));
drop policy if exists "Hosts delete their gym dates" on public.gym_dates;

drop policy if exists "Host and invitee read invites" on public.gym_date_invites;
create policy "Host and invitee read invites" on public.gym_date_invites
  for select to authenticated using (user_id = (select auth.uid()) or private.gym_date_is_host(date_id));
drop policy if exists "Hosts invite their friends" on public.gym_date_invites;
create policy "Hosts invite their friends" on public.gym_date_invites
  for insert to authenticated with check (private.gym_date_is_host(date_id) and private.is_friend(user_id));
drop policy if exists "Host or invitee remove invites" on public.gym_date_invites;
create policy "Host or invitee remove invites" on public.gym_date_invites
  for delete to authenticated using (user_id = (select auth.uid()) or private.gym_date_is_host(date_id));

-- You see your own reply, every reply to dates you host, and replies from your own
-- friends. A friend-of-a-friend's reply stays hidden; it only shows up in the counts.
drop policy if exists "Friends read replies" on public.gym_date_rsvps;
create policy "Friends read replies" on public.gym_date_rsvps
  for select to authenticated using (
    user_id = (select auth.uid())
    or private.gym_date_is_host(date_id)
    or (private.gym_date_visible(date_id) and private.is_friend(user_id))
  );
drop policy if exists "Users reply to open dates they can see" on public.gym_date_rsvps;
create policy "Users reply to open dates they can see" on public.gym_date_rsvps
  for insert to authenticated with check (user_id = (select auth.uid()) and private.gym_date_open(date_id));
drop policy if exists "Users change their reply while open" on public.gym_date_rsvps;
create policy "Users change their reply while open" on public.gym_date_rsvps
  for update to authenticated using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()) and private.gym_date_open(date_id));
drop policy if exists "Users remove their reply" on public.gym_date_rsvps;
create policy "Users remove their reply" on public.gym_date_rsvps
  for delete to authenticated using (user_id = (select auth.uid()));

-- Earlier drafts of this migration put the helpers in public.
drop function if exists public.gym_date_visible(uuid);
drop function if exists public.gym_date_is_host(uuid);
drop function if exists public.gym_date_open(uuid);

-- New dates must start between 15 minutes ago and 60 days ahead; the host is
-- always "going". Server time decides, so a wrong phone clock can't break it.
create or replace function private.gym_dates_before_write()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' or new.starts_at is distinct from old.starts_at then
    if new.starts_at < now() - interval '15 minutes' or new.starts_at > now() + interval '60 days' then
      raise exception 'A gym date must start between now and 60 days from now' using errcode = '22023';
    end if;
  end if;
  if tg_op = 'INSERT' then
    new.created_at := now();
    new.cancelled_at := null;
  elsif old.cancelled_at is not null and new.cancelled_at is distinct from old.cancelled_at then
    raise exception 'A cancelled gym date stays cancelled' using errcode = '22023';
  end if;
  new.activity_at := now();
  new.gym := btrim(new.gym);
  return new;
end;
$$;
revoke all on function private.gym_dates_before_write() from public, anon, authenticated;
drop trigger if exists gym_dates_before_write on public.gym_dates;
create trigger gym_dates_before_write before insert or update on public.gym_dates
  for each row execute function private.gym_dates_before_write();

create or replace function private.gym_dates_add_host()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.gym_date_rsvps (date_id, user_id, status)
  values (new.id, new.host_id, 'going')
  on conflict (date_id, user_id) do nothing;
  return new;
end;
$$;
revoke all on function private.gym_dates_add_host() from public, anon, authenticated;
drop trigger if exists gym_dates_add_host on public.gym_dates;
create trigger gym_dates_add_host after insert on public.gym_dates
  for each row execute function private.gym_dates_add_host();

-- Replies cannot move to another date; check-in uses server time and only works
-- from 30 minutes before the start until the end; saying "no" clears it.
create or replace function private.gym_date_rsvps_before_write()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  g public.gym_dates;
begin
  if tg_op = 'UPDATE' and (new.date_id <> old.date_id or new.user_id <> old.user_id) then
    raise exception 'A reply belongs to one date' using errcode = '42501';
  end if;
  new.updated_at := now();
  if new.status = 'no' then
    new.checked_in_at := null;
  elsif new.checked_in_at is not null and (tg_op = 'INSERT' or old.checked_in_at is null) then
    select * into g from public.gym_dates where id = new.date_id;
    if now() < g.starts_at - interval '30 minutes'
       or now() > g.starts_at + make_interval(mins => g.duration_min) then
      raise exception 'Check-in opens 30 minutes before the start' using errcode = '22023';
    end if;
    new.checked_in_at := now();
    new.status := 'going';
  elsif tg_op = 'UPDATE' and new.checked_in_at is not null then
    new.checked_in_at := old.checked_in_at;
  end if;
  return new;
end;
$$;
revoke all on function private.gym_date_rsvps_before_write() from public, anon, authenticated;
drop trigger if exists gym_date_rsvps_before_write on public.gym_date_rsvps;
create trigger gym_date_rsvps_before_write before insert or update on public.gym_date_rsvps
  for each row execute function private.gym_date_rsvps_before_write();

-- Any reply or invite change touches its date, which is what live updates watch.
create or replace function private.gym_date_touch()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.gym_dates set activity_at = now()
  where id = case when tg_op = 'DELETE' then old.date_id else new.date_id end;
  return null;
end;
$$;
revoke all on function private.gym_date_touch() from public, anon, authenticated;
drop trigger if exists gym_date_rsvps_touch on public.gym_date_rsvps;
create trigger gym_date_rsvps_touch after insert or update or delete on public.gym_date_rsvps
  for each row execute function private.gym_date_touch();
drop trigger if exists gym_date_invites_touch on public.gym_date_invites;
create trigger gym_date_invites_touch after insert or update or delete on public.gym_date_invites
  for each row execute function private.gym_date_touch();

-- Earlier drafts kept the trigger functions in public.
drop function if exists public.gym_dates_before_write();
drop function if exists public.gym_dates_add_host();
drop function if exists public.gym_date_rsvps_before_write();

-- Ending a friendship (unfriend or block) also ends the shared gym-date state:
-- replies to each other's dates and invites between the two are removed, so a
-- blocked person no longer sees you as "going" and old invites never come back.
create or replace function private.gym_dates_forget_pair(a uuid, b uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  delete from public.gym_date_rsvps r using public.gym_dates g
  where r.date_id = g.id and ((g.host_id = a and r.user_id = b) or (g.host_id = b and r.user_id = a));
  delete from public.gym_date_invites i using public.gym_dates g
  where i.date_id = g.id and ((g.host_id = a and i.user_id = b) or (g.host_id = b and i.user_id = a));
$$;
revoke all on function private.gym_dates_forget_pair(uuid, uuid) from public, anon, authenticated;

create or replace function private.friend_requests_after_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if old.status = 'accepted' then
    perform private.gym_dates_forget_pair(old.requester_id, old.target_id);
  end if;
  return old;
end;
$$;
revoke all on function private.friend_requests_after_delete() from public, anon, authenticated;
drop trigger if exists friend_requests_after_delete on public.friend_requests;
create trigger friend_requests_after_delete after delete on public.friend_requests
  for each row execute function private.friend_requests_after_delete();

create or replace function private.friend_blocks_forget()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  perform private.gym_dates_forget_pair(new.blocker_id, new.blocked_id);
  return new;
end;
$$;
revoke all on function private.friend_blocks_forget() from public, anon, authenticated;
drop trigger if exists friend_blocks_forget on public.friend_blocks;
create trigger friend_blocks_forget after insert on public.friend_blocks
  for each row execute function private.friend_blocks_forget();

-- Reply counts for dates the caller can see, including friends-of-friends they
-- cannot read individually.
create or replace function public.gym_date_counts(ids uuid[])
returns table (date_id uuid, going integer, maybe integer, here integer)
language sql
stable
security definer
set search_path = ''
as $$
  select r.date_id,
         count(*) filter (where r.status = 'going')::integer,
         count(*) filter (where r.status = 'maybe')::integer,
         count(*) filter (where r.checked_in_at is not null)::integer
  from public.gym_date_rsvps r
  where r.date_id = any (ids) and private.gym_date_visible(r.date_id)
  group by r.date_id;
$$;
revoke all on function public.gym_date_counts(uuid[]) from public, anon;
grant execute on function public.gym_date_counts(uuid[]) to authenticated;

-- Live updates. Realtime filters inserts and updates by these policies, but it
-- sends every DELETE to every subscriber with the row's primary key. So only
-- gym_dates is published: its key is a random id, rows are never deleted by
-- the app (dates are cancelled), and reply/invite changes arrive as updates of
-- activity_at. The reply and invite tables must stay unpublished, because their
-- keys reveal who replied to which date.
do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['gym_date_rsvps', 'gym_date_invites'] loop
      if exists (
        select 1 from pg_publication_tables
        where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
      ) then
        execute format('alter publication supabase_realtime drop table public.%I', t);
      end if;
    end loop;
    if not exists (
      select 1 from pg_publication_tables
      where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'gym_dates'
    ) then
      alter publication supabase_realtime add table public.gym_dates;
    end if;
  end if;
end;
$$;

-- ===== 20261024000003_policy_performance.sql =====
-- Re-creates the original policies with (select auth.uid()), which Postgres
-- evaluates once per query instead of once per row (Supabase performance
-- advisor). Behaviour is unchanged. Also removes the anon key's rights on the
-- original tables. Safe to run more than once.

drop policy if exists "Users create their profile" on public.profiles;
create policy "Users create their profile" on public.profiles
  for insert to authenticated with check (id = (select auth.uid()));
drop policy if exists "Users update their profile" on public.profiles;
create policy "Users update their profile" on public.profiles
  for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));

drop policy if exists "Participants read friend requests" on public.friend_requests;
create policy "Participants read friend requests" on public.friend_requests
  for select to authenticated using (requester_id = (select auth.uid()) or target_id = (select auth.uid()));
drop policy if exists "Users send friend requests" on public.friend_requests;
create policy "Users send friend requests" on public.friend_requests
  for insert to authenticated with check (requester_id = (select auth.uid()) and status = 'pending');
drop policy if exists "Recipient accepts request" on public.friend_requests;
create policy "Recipient accepts request" on public.friend_requests
  for update to authenticated using (target_id = (select auth.uid()) and status = 'pending')
  with check (target_id = (select auth.uid()) and status = 'accepted');

drop policy if exists "Owner or accepted friends read shared workouts" on public.shared_workouts;
create policy "Owner or accepted friends read shared workouts" on public.shared_workouts
  for select to authenticated using (
    owner_id = (select auth.uid()) or exists (
      select 1 from public.friend_requests f
      where f.status = 'accepted' and
        ((f.requester_id = (select auth.uid()) and f.target_id = owner_id) or
         (f.target_id = (select auth.uid()) and f.requester_id = owner_id))
    )
  );
drop policy if exists "Users share their selected workouts" on public.shared_workouts;
create policy "Users share their selected workouts" on public.shared_workouts
  for insert to authenticated with check (owner_id = (select auth.uid()));
drop policy if exists "Owners remove their shared workouts" on public.shared_workouts;
create policy "Owners remove their shared workouts" on public.shared_workouts
  for delete to authenticated using (owner_id = (select auth.uid()));

drop policy if exists "Owner or friends read published stats" on public.leaderboard_stats;
create policy "Owner or friends read published stats" on public.leaderboard_stats
  for select to authenticated using (
    user_id = (select auth.uid()) or exists (
      select 1 from public.friend_requests f
      where f.status = 'accepted' and
        ((f.requester_id = (select auth.uid()) and f.target_id = user_id) or
         (f.target_id = (select auth.uid()) and f.requester_id = user_id))
    )
  );
drop policy if exists "Users publish their own aggregate stats" on public.leaderboard_stats;
create policy "Users publish their own aggregate stats" on public.leaderboard_stats
  for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists "Users update their own aggregate stats" on public.leaderboard_stats;
create policy "Users update their own aggregate stats" on public.leaderboard_stats
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
drop policy if exists "Users remove their published stats" on public.leaderboard_stats;
create policy "Users remove their published stats" on public.leaderboard_stats
  for delete to authenticated using (user_id = (select auth.uid()));

drop policy if exists "Users create their own workout plan" on public.workout_plans;
create policy "Users create their own workout plan" on public.workout_plans
  for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists "Users update their own workout plan" on public.workout_plans;
create policy "Users update their own workout plan" on public.workout_plans
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
drop policy if exists "Users remove their own workout plan" on public.workout_plans;
create policy "Users remove their own workout plan" on public.workout_plans
  for delete to authenticated using (user_id = (select auth.uid()));

drop policy if exists "Users record their own body weight" on public.body_weight_logs;
create policy "Users record their own body weight" on public.body_weight_logs
  for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists "Users update their own body weight" on public.body_weight_logs;
create policy "Users update their own body weight" on public.body_weight_logs
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
drop policy if exists "Users delete their own body weight" on public.body_weight_logs;
create policy "Users delete their own body weight" on public.body_weight_logs
  for delete to authenticated using (user_id = (select auth.uid()));

drop policy if exists "Users read their own workout data" on public.workout_data;
create policy "Users read their own workout data" on public.workout_data
  for select to authenticated using (user_id = (select auth.uid()));
drop policy if exists "Users create their own workout data" on public.workout_data;
create policy "Users create their own workout data" on public.workout_data
  for insert to authenticated with check (user_id = (select auth.uid()));
drop policy if exists "Users update their own workout data" on public.workout_data;
create policy "Users update their own workout data" on public.workout_data
  for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
drop policy if exists "Users remove their own workout data" on public.workout_data;
create policy "Users remove their own workout data" on public.workout_data
  for delete to authenticated using (user_id = (select auth.uid()));

-- Nobody signed out needs these tables; keep them out of reach of the anon key.
revoke all on public.profiles, public.friend_requests, public.shared_workouts, public.leaderboard_stats,
  public.workout_plans, public.body_weight_logs, public.workout_data from anon;

-- Signed-in users only need to read and write rows (row-level security decides
-- which). TRUNCATE in particular ignores row-level security.
revoke truncate, references, trigger on public.profiles, public.friend_requests, public.shared_workouts,
  public.leaderboard_stats, public.workout_plans, public.body_weight_logs, public.workout_data from authenticated;
do $$
begin
  if current_setting('server_version_num')::int >= 170000 then
    execute 'revoke maintain on public.profiles, public.friend_requests, public.shared_workouts, public.leaderboard_stats,
      public.workout_plans, public.body_weight_logs, public.workout_data from authenticated';
  end if;
end;
$$;

-- ===== 20261024000004_storage_limits.sql =====
-- Per-account size limits, so a single account can't fill the database or make
-- its friends' leaderboard slow. They are far above real use (years of daily
-- workouts take a few MB). NOT VALID: only new writes are checked, so rows that
-- already exist never block this migration.

alter table public.workout_plans drop constraint if exists workout_plans_size;
alter table public.workout_plans add constraint workout_plans_size
  check (octet_length(plan::text) <= 1048576) not valid;

alter table public.workout_data drop constraint if exists workout_data_size;
alter table public.workout_data add constraint workout_data_size check (
  octet_length(logs::text) + octet_length(coalesce(progress::text, ''))
  + octet_length(deleted_sessions::text) + octet_length(daily_summaries::text) + octet_length(deleted_dates::text)
  + octet_length(bypass_days::text) + octet_length(legacy_stats::text) + octet_length(stats_snapshot::text) <= 8388608
) not valid;

-- Weigh-ins: a plausible date, and at most 20,000 per account (55 years of daily entries).
create or replace function private.body_weight_limits()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- One writer per account at a time, so parallel requests can't all pass the count.
  perform pg_advisory_xact_lock(hashtextextended('weights:' || new.user_id::text, 0));
  if new.log_date < date '1900-01-01' or new.log_date > current_date + 2 then
    raise exception 'A weigh-in needs a date between 1900 and today' using errcode = '22023';
  end if;
  if tg_op = 'INSERT'
     and not exists (select 1 from public.body_weight_logs b where b.user_id = new.user_id and b.log_date = new.log_date) -- a correction, not a new day
     and (select count(*) from public.body_weight_logs b where b.user_id = new.user_id) >= 20000 then
    raise exception 'Too many weigh-ins on this account' using errcode = '54000';
  end if;
  return new;
end;
$$;
revoke all on function private.body_weight_limits() from public, anon, authenticated;
drop trigger if exists body_weight_limits on public.body_weight_logs;
create trigger body_weight_limits before insert or update on public.body_weight_logs
  for each row execute function private.body_weight_limits();

-- Shared routines and gym dates: a bounded number per account, so nobody can
-- fill the database or flood their friends' lists.
create or replace function private.count_limits()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- One writer per account and table at a time, so parallel requests can't all pass the count.
  if tg_table_name = 'shared_workouts' then
    perform pg_advisory_xact_lock(hashtextextended('shared:' || new.owner_id::text, 0));
    new.created_at := now(); -- server time, so nobody can pin their shares to the top of the list
    if (select count(*) from public.shared_workouts s where s.owner_id = new.owner_id) >= 50 then
      raise exception 'You can share up to 50 routines' using errcode = '54000';
    end if;
  elsif tg_table_name = 'gym_dates' then
    perform pg_advisory_xact_lock(hashtextextended('dates:' || new.host_id::text, 0));
    if (select count(*) from public.gym_dates g where g.host_id = new.host_id and g.created_at > now() - interval '1 day') >= 20 then
      raise exception 'You can post up to 20 gym dates a day' using errcode = '54000';
    end if;
    if (select count(*) from public.gym_dates g where g.host_id = new.host_id and g.cancelled_at is null and g.starts_at > now()) >= 30 then
      raise exception 'You can have up to 30 upcoming gym dates' using errcode = '54000';
    end if;
  end if;
  return new;
end;
$$;
revoke all on function private.count_limits() from public, anon, authenticated;
drop trigger if exists shared_workouts_count_limit on public.shared_workouts;
create trigger shared_workouts_count_limit before insert on public.shared_workouts
  for each row execute function private.count_limits();
drop trigger if exists gym_dates_count_limit on public.gym_dates;
create trigger gym_dates_count_limit before insert on public.gym_dates
  for each row execute function private.count_limits();

-- ===== 20261024000005_plain_text.sql =====
-- No markup from other people reaches the original app (still on some phones),
-- which puts routine and exercise names and the rest-day picture into the page
-- unescaped:
--  * shared routines (the only names that come from someone else) are refused
--    when they carry markup characters; this app cleans them before sharing,
--    and existing ones that carry them are removed;
--  * the rest-day picture must be image data; anything else is dropped (the
--    original app's "Reset" stores 'rest.png', which then means "none").
-- A user's own plan and history keep names exactly as typed: both apps
-- identify routines and workouts by name, and renaming them would duplicate
-- routines and workouts in the original app.

create or replace function private.clean_plan()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.plan ? 'restImage' and new.plan ->> 'restImage' is not null
     and new.plan ->> 'restImage' !~ '^data:image/(jpeg|png|webp|gif);base64,[A-Za-z0-9+/]+=*$' then
    new.plan := new.plan - 'restImage';
  end if;
  return new;
end;
$$;
revoke all on function private.clean_plan() from public, anon, authenticated;
drop trigger if exists workout_plans_clean on public.workout_plans;
create trigger workout_plans_clean before insert or update on public.workout_plans
  for each row execute function private.clean_plan();

-- Shared routines: refused when they carry markup; existing ones that do are
-- removed (the owner's own plan keeps the routine), so a payload planted
-- before this deploy can't reach the original app either.
alter table public.shared_workouts drop constraint if exists shared_workouts_plain_text;
alter table public.shared_workouts add constraint shared_workouts_plain_text
  check (title !~ '[<>"`]' and workout::text !~ '[<>`]|(^|[^\\])(\\\\)*\\"') not valid;
delete from public.shared_workouts where title ~ '[<>"`]' or workout::text ~ '[<>`]|(^|[^\\])(\\\\)*\\"';
alter table public.shared_workouts validate constraint shared_workouts_plain_text;

-- ...and must look like a routine: the original app crashes or freezes on a
-- copied entry that is not an exercise, or on an absurd number of sets.
alter table public.shared_workouts drop constraint if exists shared_workouts_shape;
-- (strict: lax mode would look inside nested arrays such as [[]].)
alter table public.shared_workouts add constraint shared_workouts_shape check (
  not jsonb_path_exists(workout, 'strict $[*] ? (@.type() != "object")')
  and not jsonb_path_exists(workout, '$[*] ? (!exists(@.name) || @.name.type() != "string")')
  and not jsonb_path_exists(workout, '$[*].sets ? (@.type() != "number" || @ < 1 || @ > 40)')
) not valid;
delete from public.shared_workouts where
  jsonb_path_exists(workout, 'strict $[*] ? (@.type() != "object")')
  or jsonb_path_exists(workout, '$[*] ? (!exists(@.name) || @.name.type() != "string")')
  or jsonb_path_exists(workout, '$[*].sets ? (@.type() != "number" || @ < 1 || @ > 40)');
alter table public.shared_workouts validate constraint shared_workouts_shape;

-- The size check added by the privacy migration is enforced for every row too.
delete from public.shared_workouts where not (jsonb_array_length(workout) <= 60 and pg_column_size(workout) < 32768);
alter table public.shared_workouts validate constraint shared_workouts_size_check;

-- Earlier drafts of this migration cleaned or refused whole plans and histories.
alter table public.workout_plans drop constraint if exists workout_plans_plain_text;
alter table public.workout_data drop constraint if exists workout_data_plain_text;
drop trigger if exists workout_data_clean on public.workout_data;
drop function if exists private.clean_workout_data();
drop function if exists private.plain_json(jsonb);

-- ===== 20261024000006_verify_access.sql =====
-- Stops the deploy that applies it if the live database has row-level
-- security policies (by name), callable functions (by signature), API-readable
-- views or live-update tables that these migrations don't define. Policies
-- with these names were re-created by the migrations before this one.
-- Policies combine with OR, so one extra permissive policy made in the
-- dashboard (e.g. "Enable read access for all users") would quietly undo the
-- privacy rules. If this fails, look at what it lists and drop it, or add it
-- here on purpose.
do $$
declare
  extra text;
begin
  select string_agg(p.tablename || ': ' || p.policyname, '; ') into extra
  from pg_policies p
  where p.schemaname = 'public'
    and (p.tablename, p.policyname) not in (values
    ('body_weight_logs', 'Users delete their own body weight'),
    ('body_weight_logs', 'Users read their own body weight'),
    ('body_weight_logs', 'Users record their own body weight'),
    ('body_weight_logs', 'Users update their own body weight'),
    ('friend_blocks', 'Users block others'),
    ('friend_blocks', 'Users see their blocks'),
    ('friend_blocks', 'Users unblock others'),
    ('friend_requests', 'Participants read friend requests'),
    ('friend_requests', 'Participants remove friend requests'),
    ('friend_requests', 'Recipient accepts request'),
    ('friend_requests', 'Users send friend requests'),
    ('gym_date_invites', 'Host and invitee read invites'),
    ('gym_date_invites', 'Host or invitee remove invites'),
    ('gym_date_invites', 'Hosts invite their friends'),
    ('gym_date_rsvps', 'Friends read replies'),
    ('gym_date_rsvps', 'Users change their reply while open'),
    ('gym_date_rsvps', 'Users remove their reply'),
    ('gym_date_rsvps', 'Users reply to open dates they can see'),
    ('gym_dates', 'Host and invited friends read gym dates'),
    ('gym_dates', 'Hosts edit their gym dates'),
    ('gym_dates', 'Users host their own gym dates'),
    ('leaderboard_stats', 'Owner or friends read published stats'),
    ('leaderboard_stats', 'Users publish their own aggregate stats'),
    ('leaderboard_stats', 'Users remove their published stats'),
    ('leaderboard_stats', 'Users update their own aggregate stats'),
    ('profiles', 'Users create their profile'),
    ('profiles', 'Users read related profiles'),
    ('profiles', 'Users update their profile'),
    ('shared_workouts', 'Owner or accepted friends read shared workouts'),
    ('shared_workouts', 'Owners remove their shared workouts'),
    ('shared_workouts', 'Users share their selected workouts'),
    ('workout_data', 'Users create their own workout data'),
    ('workout_data', 'Users read their own workout data'),
    ('workout_data', 'Users remove their own workout data'),
    ('workout_data', 'Users update their own workout data'),
    ('workout_plans', 'Users create their own workout plan'),
    ('workout_plans', 'Users read their own workout plan'),
    ('workout_plans', 'Users remove their own workout plan'),
    ('workout_plans', 'Users update their own workout plan'));
  if extra is not null then
    raise exception 'Unexpected row-level security policies: %', extra;
  end if;

  -- Exact signatures, so an overload left over from SQL-editor work is caught too.
  select string_agg(p.oid::regprocedure::text, '; ') into extra
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'))
    and p.oid::regprocedure::text not in ('change_username(text)', 'delete_my_account()', 'find_profile(text)', 'friend_summaries()', 'gym_date_counts(uuid[])', 'my_blocks()', 'save_my_weights(jsonb)',
      'change_username(text,uuid)', 'save_my_weights(jsonb,uuid)'); -- the last two from 20261025000000 (for new projects and the tests)
  if extra is not null then
    raise exception 'Unexpected functions callable through the API: %', extra;
  end if;

  select string_agg(c.relname, '; ') into extra
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('r', 'p') and not c.relrowsecurity;
  if extra is not null then
    raise exception 'Tables without row-level security: %', extra;
  end if;

  -- Views and other relations bypass row-level security unless built for it; the app needs none.
  select string_agg(c.relname, '; ') into extra
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relkind in ('v', 'm', 'f')
    and (has_table_privilege('anon', c.oid, 'select') or has_table_privilege('authenticated', c.oid, 'select'));
  if extra is not null then
    raise exception 'Views readable through the API: %', extra;
  end if;

  -- Live updates may carry only gym dates (replies would reveal who joined).
  select string_agg(t.tablename, '; ') into extra
  from pg_publication_tables t
  where t.pubname = 'supabase_realtime' and t.schemaname = 'public' and t.tablename <> 'gym_dates';
  if extra is not null then
    raise exception 'Unexpected tables in live updates: %', extra;
  end if;
end;
$$;

-- ===== 20261025000000_expected_user.sql =====
-- Writes made for one account only. All browser tabs share one stored login,
-- so a request that a sync started for account A can be sent after account B
-- signed in in another tab, and would then be saved in B's account. These
-- variants take the account the app means and refuse anything else. The
-- one-argument versions stay for app versions that do not send it yet.

create function public.save_my_weights(entries jsonb, expected_user uuid)
returns table (log_date date, updated_at timestamptz, outcome text)
language plpgsql
set search_path = ''
as $$
begin
  if expected_user is distinct from auth.uid() then
    raise exception 'This request belongs to an account that is no longer signed in.' using errcode = '42501';
  end if;
  return query select * from public.save_my_weights(entries);
end
$$;
revoke all on function public.save_my_weights(jsonb, uuid) from public, anon;
grant execute on function public.save_my_weights(jsonb, uuid) to authenticated;

create function public.change_username(name text, expected_user uuid)
returns text
language plpgsql
set search_path = ''
as $$
begin
  if expected_user is distinct from auth.uid() then
    raise exception 'This request belongs to an account that is no longer signed in.' using errcode = '42501';
  end if;
  return public.change_username(name);
end
$$;
revoke all on function public.change_username(text, uuid) from public, anon;
grant execute on function public.change_username(text, uuid) to authenticated;

-- ===== 20261025000001_friend_leaderboards.sql =====
-- Share only the exercise best weights the user selected for friend leaderboards.
alter table public.leaderboard_stats
  add column if not exists exercise_bests jsonb not null default '{}'::jsonb;

alter table public.leaderboard_stats
  drop constraint if exists leaderboard_stats_exercise_bests_object;
alter table public.leaderboard_stats
  add constraint leaderboard_stats_exercise_bests_object
  check (jsonb_typeof(exercise_bests) = 'object' and pg_column_size(exercise_bests) <= 8192);

-- What friends see about each other. Stats and plan counts only for people who
-- published them (a leaderboard row); totals come from their synced history
-- when there is one. Streaks are reported by the app, since they depend on the
-- weekly plan.
drop function if exists public.friend_summaries();
create function public.friend_summaries()
returns table (
  user_id uuid, username text, workouts_count integer, volume_kg_reps bigint,
  total_seconds bigint, current_streak integer, best_streak integer, exercise_bests jsonb,
  weight_kg numeric, weight_date date, routines integer, exercises integer
)
language sql
stable
security definer
set search_path = ''
as $$
  with people as (
    select auth.uid() as id
    union
    select case when f.requester_id = auth.uid() then f.target_id else f.requester_id end
    from public.friend_requests f
    where f.status = 'accepted' and (f.requester_id = auth.uid() or f.target_id = auth.uid())
  )
  select p.id, p.username,
         case when s.user_id is not null then coalesce(t.workouts, s.workouts_count) end,
         case when s.user_id is not null then coalesce(t.volume, s.volume_kg_reps) end,
         case when s.user_id is not null then coalesce(t.seconds, s.total_seconds) end,
         s.current_streak,
         s.best_streak,
         case when s.user_id is not null then coalesce(s.exercise_bests, '{}'::jsonb) else '{}'::jsonb end,
         case when p.share_weight or p.id = auth.uid() then w.weight_kg end,
         case when p.share_weight or p.id = auth.uid() then w.log_date end,
         case when s.user_id is not null or p.id = auth.uid() then
           coalesce((select count(*) from jsonb_object_keys(case when jsonb_typeof(wp.plan -> 'workouts') = 'object' then wp.plan -> 'workouts' else '{}'::jsonb end)), 0)::integer end,
         case when s.user_id is not null or p.id = auth.uid() then
           coalesce((select sum(jsonb_array_length(v)) from jsonb_each(case when jsonb_typeof(wp.plan -> 'workouts') = 'object' then wp.plan -> 'workouts' else '{}'::jsonb end) as e(k, v)
                     where jsonb_typeof(v) = 'array'), 0)::integer end
  from people x
  join public.profiles p on p.id = x.id
  left join public.leaderboard_stats s on s.user_id = p.id
  left join public.workout_plans wp on wp.user_id = p.id
  left join public.workout_data wd on wd.user_id = p.id and s.user_id is not null
  left join lateral private.workout_totals(wd.logs) t on wd.user_id is not null
  left join lateral (
    select b.weight_kg, b.log_date from public.body_weight_logs b
    where b.user_id = p.id order by b.log_date desc limit 1
  ) w on true
  where auth.uid() is not null;
$$;
revoke all on function public.friend_summaries() from public, anon;
grant execute on function public.friend_summaries() to authenticated;

